from pathlib import Path
from collections import Counter
import re, json, sys

from pypdf import PdfReader
from docx import Document
from pptx import Presentation

BASE = Path('/root/papers/all')

TOPICS = {
    "LLM": [
        "large language model", "language model", "llm", "gpt", "chatgpt",
        "transformer", "attention", "prompt", "instruction tuning",
        "fine-tuning", "finetuning", "pretraining", "self-supervised",
        "token", "rlhf", "alignment", "foundation model", "bert", "llama",
    ],
    "trapped_ion_and_qc": [
        "trapped ion", "ion trap", "paul trap", "penning trap",
        "quantum computing", "quantum computer", "quantum computation",
        "qubit", "quantum gate", "entanglement", "quantum algorithm",
        "quantum error", "quantum error correction", "decoherence",
        "quantum control", "rydberg", "quantum information",
    ],
    "black_hole": [
        "black hole", "event horizon", "hawking", "singularity",
        "schwarzschild", "kerr", "accretion", "gravitational",
        "general relativity", "spacetime", "einstein", "horizon",
    ],
    "DNA": [
        "dna", "genome", "genomics", "sequencing", "nucleotide",
        "chromosome", "gene", "genetic", "rna", "crispr",
        "double helix", "molecular biology", "protein", "transcription",
    ],
    "music_history": [
        "music", "composer", "baroque", "classical", "romantic",
        "renaissance", "medieval", "jazz", "symphony", "opera",
        "sonata", "fugue", "musicology", "concert", "orchestra",
    ],
}

EXTS = {'.pdf', '.docx', '.pptx'}

# keyword weights: longer phrases get higher weight
WEIGHTS = {}
for topic, kws in TOPICS.items():
    for kw in kws:
        WEIGHTS[kw] = max(1, len(kw.split()))


def extract_text(path: Path, max_chars=40000):
    ext = path.suffix.lower()
    text = ""
    try:
        if ext == ".pdf":
            reader = PdfReader(str(path))
            for page in reader.pages:
                text += (page.extract_text() or "") + "\n"
                if len(text) >= max_chars:
                    break
        elif ext == ".docx":
            doc = Document(str(path))
            for p in doc.paragraphs:
                text += p.text + "\n"
                if len(text) >= max_chars:
                    break
        elif ext == ".pptx":
            prs = Presentation(str(path))
            for slide in prs.slides:
                for shape in slide.shapes:
                    if hasattr(shape, "text"):
                        text += shape.text + "\n"
                if len(text) >= max_chars:
                    break
    except Exception:
        return ""
    return text[:max_chars]


def score_text(text: str, fname: str):
    text_l = text.lower()
    fname_l = fname.lower()
    scores = {topic: 0 for topic in TOPICS}

    for topic, kws in TOPICS.items():
        s = 0
        for kw in kws:
            # phrase match in text
            if kw in text_l:
                s += 3 * WEIGHTS[kw]
                s += text_l.count(kw)
            # filename hints
            if kw.replace(" ", "") in fname_l or kw in fname_l:
                s += 2 * WEIGHTS[kw]
        scores[topic] = s

    # extra heuristics
    # penalize generic "music" when "quantum" is strong, etc. handled by score
    return scores

results = []

for path in sorted(p for p in BASE.iterdir() if p.is_file() and p.suffix.lower() in EXTS):
    text = extract_text(path)
    scores = score_text(text, path.name)
    # pick top topic; if all zero, default to music_history
    top_topic = max(scores, key=scores.get)
    top_score = scores[top_topic]
    if top_score == 0:
        top_topic = "music_history"
    results.append({
        "file": path.name,
        "topic": top_topic,
        "scores": scores,
        "text_len": len(text),
    })

# summary
counts = Counter(r["topic"] for r in results)
print("COUNTS", dict(counts))

# low confidence or ties
low = []
for r in results:
    scores = r["scores"]
    sorted_scores = sorted(scores.items(), key=lambda x: x[1], reverse=True)
    if sorted_scores[0][1] == 0:
        low.append((r["file"], r["topic"], sorted_scores[:3], r["text_len"]))
    elif len(sorted_scores) > 1 and sorted_scores[0][1] == sorted_scores[1][1]:
        low.append((r["file"], r["topic"], sorted_scores[:3], r["text_len"]))
    elif sorted_scores[0][1] <= 4:
        low.append((r["file"], r["topic"], sorted_scores[:3], r["text_len"]))

print("LOW_CONF", len(low))
for item in low[:40]:
    print(item)

# save mapping for later
out = Path('/root/papers/classification.json')
out.write_text(json.dumps(results, indent=2))
print("WROTE", out)
